import React, { useState, useMemo } from 'react';
import { 
  User, 
  ShieldAlert, 
  Dna, 
  Brain, 
  Activity, 
  ThermometerSnowflake 
} from 'lucide-react';
import PatientInfoForm from './components/PatientInfoForm';
import RiskStratification from './components/RiskStratification';
import MPALModule from './components/MPALModule';
import CNSLModule from './components/CNSLModule';
import LASPModule from './components/LASPModule';
import TLSModule from './components/TLSModule';
import { PatientInfo } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('patient');
  const [patient, setPatient] = useState<PatientInfo>({
    name: '',
    gender: '',
    age: '',
    height: '',
    weight: '',
    initialWbc: ''
  });

  const bsa = useMemo(() => {
    const h = parseFloat(patient.height);
    const w = parseFloat(patient.weight);
    if (isNaN(h) || isNaN(w)) return 0;
    // Mosteller formula: sqrt((h*w)/3600)
    return Math.sqrt((h * w) / 3600);
  }, [patient.height, patient.weight]);

  const renderContent = () => {
    switch (activeTab) {
      case 'patient':
        return <PatientInfoForm patient={patient} setPatient={setPatient} bsa={bsa} />;
      case 'risk':
        return <RiskStratification patient={patient} />;
      case 'mpal':
        return <MPALModule />;
      case 'cnsl':
        return <CNSLModule />;
      case 'lasp':
        return <LASPModule bsa={bsa} patient={patient} />;
      case 'tls':
        return <TLSModule patient={patient} bsa={bsa} />;
      default:
        return null;
    }
  };

  const tabs = [
    { id: 'patient', icon: User, label: '病人信息' },
    { id: 'risk', icon: ShieldAlert, label: '危险度' },
    { id: 'mpal', icon: Dna, label: 'MPAL' },
    { id: 'cnsl', icon: Brain, label: 'CNSL' },
    { id: 'lasp', icon: Activity, label: 'L-ASP' },
    { id: 'tls', icon: ThermometerSnowflake, label: 'TLS' },
  ];

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-[#F2F2F7]">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/80 ios-blur border-b border-gray-200 px-4 py-4">
        <h1 className="text-xl font-bold text-center tracking-tight">SCCCG-ALL-2025</h1>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-24 px-4 pt-4">
        {renderContent()}
      </main>

      {/* Tab Bar */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/90 ios-blur border-t border-gray-200 px-2 pb-safe-area-inset-bottom">
        <div className="flex justify-around items-center h-16">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex flex-col items-center justify-center flex-1 space-y-1 transition-colors ${
                activeTab === tab.id ? 'text-blue-600' : 'text-gray-400'
              }`}
            >
              <tab.icon size={22} strokeWidth={activeTab === tab.id ? 2.5 : 2} />
              <span className="text-[10px] font-medium">{tab.label}</span>
            </button>
          ))}
        </div>
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import IOSCard from './IOSCard';
import { PatientInfo } from '../types';

interface Props {
  bsa: number;
  patient: PatientInfo;
}

const LASPModule: React.FC<Props> = ({ bsa, patient }) => {
  const [fib, setFib] = useState('');
  const [at3, setAt3] = useState('');

  const weight = parseFloat(patient.weight);

  const getAdvice = () => {
    const f = parseFloat(fib);
    const a = parseFloat(at3);
    const advices = [];

    if (f > 0 && f < 0.3) {
      advices.push('纤维蛋白原极低: 建议补充纤维蛋白原制剂 10-20mg/kg (除非明显出血，否则不主张过激补充)。');
    } else if (f > 0 && f < 0.5) {
      advices.push('纤维蛋白原降低 (<0.5g/L): 密切观察，若有出血风险建议预防性补充。');
    }

    if (a > 0 && a < 30) {
      advices.push('AT-III 严重降低 (<30%): 极高血栓风险。必须考虑抗凝干预 (如利伐沙班或达比加群酯)。');
    } else if (a > 0 && a < 60) {
      advices.push('AT-III 降低 (<60%): 建议普通肝素 100 UI/kg/天 或低分子肝素预防血栓。');
    }

    return advices;
  };

  const getRivaroxabanSuggest = () => {
    if (!weight) return "请先在'病人信息'中录入体重";
    if (weight < 30) return "建议参考儿科专业剂量 (通常 0.1mg/kg bid 或遵循说明书)";
    if (weight < 50) return "15 mg，每日一次 (qd)";
    return "20 mg，每日一次 (qd)";
  };

  const getDabigatranSuggest = () => {
    if (!weight) return "请先在'病人信息'中录入体重";
    // Standard pediatric/adult-like reference
    if (weight < 40) return "建议参考儿科减量方案 (通常 bid 给药)";
    if (weight < 70) return "110 mg，每日两次 (bid)";
    return "150 mg，每日两次 (bid)";
  };

  const advices = getAdvice();

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300 pb-8">
      <IOSCard title="凝血指标监测">
        <div className="space-y-4">
          <div className="flex justify-between items-center border-b border-gray-50 pb-2">
            <span className="text-sm font-medium text-gray-700">纤维蛋白原 (Fib, g/L)</span>
            <input type="number" placeholder="0.0" value={fib} onChange={e => setFib(e.target.value)} className="w-24 text-right outline-none text-sm font-semibold text-blue-600" />
          </div>
          <div className="flex justify-between items-center">
            <span className="text-sm font-medium text-gray-700">抗凝血酶-III (AT-III, %)</span>
            <input type="number" placeholder="0" value={at3} onChange={e => setAt3(e.target.value)} className="w-24 text-right outline-none text-sm font-semibold text-blue-600" />
          </div>
        </div>
      </IOSCard>

      {advices.length > 0 && (
        <IOSCard title="实时处理建议">
          <ul className="space-y-3">
            {advices.map((a, i) => (
              <li key={i} className="text-xs text-red-800 bg-red-50 p-3 rounded-xl border border-red-100 flex items-start space-x-2">
                <span className="mt-1 w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                <span>{a}</span>
              </li>
            ))}
          </ul>
        </IOSCard>
      )}

      <IOSCard title="抗凝药物剂量参考 (血栓预防/治疗)">
        <div className="space-y-4">
          <div className="bg-gray-50 rounded-xl p-3">
            <h4 className="text-xs font-bold text-gray-700 mb-2 border-l-4 border-blue-500 pl-2">利伐沙班 (Rivaroxaban)</h4>
            <div className="overflow-x-auto">
              <table className="w-full text-[10px] text-left">
                <thead className="text-gray-400 font-normal">
                  <tr>
                    <th className="pb-1">体重范围</th>
                    <th className="pb-1">推荐剂量</th>
                  </tr>
                </thead>
                <tbody className="text-gray-600 divide-y divide-gray-100">
                  <tr><td className="py-1.5">&lt; 30 kg</td><td className="py-1.5">0.1 mg/kg bid 或遵循专科</td></tr>
                  <tr><td className="py-1.5">30 - 50 kg</td><td className="py-1.5">15 mg qd</td></tr>
                  <tr><td className="py-1.5">&gt; 50 kg</td><td className="py-1.5">20 mg qd</td></tr>
                </tbody>
              </table>
            </div>
            <div className="mt-2 p-2 bg-blue-50 rounded-lg border border-blue-100">
              <p className="text-[10px] text-blue-700 font-medium">当前病人建议: {getRivaroxabanSuggest()}</p>
            </div>
          </div>

          <div className="bg-gray-50 rounded-xl p-3">
            <h4 className="text-xs font-bold text-gray-700 mb-2 border-l-4 border-purple-500 pl-2">达比加群酯 (Dabigatran)</h4>
            <div className="overflow-x-auto">
              <table className="w-full text-[10px] text-left">
                <thead className="text-gray-400 font-normal">
                  <tr>
                    <th className="pb-1">体重范围</th>
                    <th className="pb-1">推荐剂量</th>
                  </tr>
                </thead>
                <tbody className="text-gray-600 divide-y divide-gray-100">
                  <tr><td className="py-1.5">40 - 70 kg</td><td className="py-1.5">110 mg bid</td></tr>
                  <tr><td className="py-1.5">&gt; 70 kg</td><td className="py-1.5">150 mg bid</td></tr>
                </tbody>
              </table>
            </div>
            <div className="mt-2 p-2 bg-purple-50 rounded-lg border border-purple-100">
              <p className="text-[10px] text-purple-700 font-medium">当前病人建议: {getDabigatranSuggest()}</p>
            </div>
          </div>
        </div>
      </IOSCard>

      <IOSCard title="L-ASP 监测及干预要点">
        <div className="text-[11px] text-gray-500 leading-relaxed space-y-2">
          <p className="flex items-start">
            <span className="mr-1 text-blue-500 font-bold">•</span>
            <span><b>监测频率:</b> 每次 L-ASP 输注前(d8, d10)及 d12-d28 每隔一天评估 Fib 和 AT-III。</span>
          </p>
          <p className="flex items-start">
            <span className="mr-1 text-blue-500 font-bold">•</span>
            <span><b>CVST 警示:</b> 警惕静脉窦血栓(CVST)，如出现无法解释的头痛、喷射性呕吐或精神萎靡，应查头部 MRI + MRV。</span>
          </p>
          <p className="flex items-start">
            <span className="mr-1 text-blue-500 font-bold">•</span>
            <span><b>Fib 补充:</b> 当 Fib &lt; 0.5g/L 且有出血倾向或需进行腰穿等有创操作时，建议补充纤维蛋白原。</span>
          </p>
          <p className="flex items-start">
            <span className="mr-1 text-blue-500 font-bold">•</span>
            <span><b>血小板支持:</b> 治疗期间若血小板 &lt; 20×10⁹/L，必须及时输注血小板，防止自发性出血。</span>
          </p>
        </div>
      </IOSCard>
    </div>
  );
};

export default LASPModule;

import React, { useState } from 'react';
import IOSCard from './IOSCard';
import { PatientInfo } from '../types';

interface Props {
  patient: PatientInfo;
  bsa: number;
}

const TLSModule: React.FC<Props> = ({ patient, bsa }) => {
  const [lineage, setLineage] = useState<'B' | 'T' | 'Burkitt'>('B');
  const [isBulky, setIsBulky] = useState(false);
  const [showFullCriteria, setShowFullCriteria] = useState(false);

  const wbc = parseFloat(patient.initialWbc) || 0;

  // 1. 风险分层 (参照表4)
  const getRiskStratification = () => {
    if (lineage === 'Burkitt' || wbc >= 100) {
      return { level: '高危 (High Risk)', color: 'text-red-600', bgColor: 'bg-red-50', borderColor: 'border-red-100' };
    }
    if (lineage === 'T-ALL' || (lineage === 'B-ALL' && wbc >= 25) || isBulky) {
      return { level: '中危 (Intermediate Risk)', color: 'text-orange-500', bgColor: 'bg-orange-50', borderColor: 'border-orange-100' };
    }
    return { level: '低危 (Low Risk)', color: 'text-green-600', bgColor: 'bg-green-50', borderColor: 'border-green-100' };
  };

  const risk = getRiskStratification();

  // 2. 水化量计算 (参照表6/7)
  const hydrationVolume = bsa > 0 ? bsa * 3000 : 0; // 建议 2500-3000ml/m2
  const dripRate = hydrationVolume > 0 ? (hydrationVolume / 24).toFixed(1) : '0';

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300 pb-20">
      {/* 风险评估输入 */}
      <IOSCard title="TLS 风险因子评估 (表4)">
        <div className="space-y-4">
          <div className="flex items-center justify-between border-b border-gray-50 pb-3">
            <span className="text-sm font-medium text-gray-700">疾病类型</span>
            <div className="flex bg-gray-100 p-1 rounded-lg">
              {(['B', 'T', 'Burkitt'] as const).map((t) => (
                <button
                  key={t}
                  onClick={() => setLineage(t)}
                  className={`px-3 py-1 text-xs rounded-md transition-all ${
                    lineage === t ? 'bg-white shadow-sm text-blue-600 font-bold' : 'text-gray-500'
                  }`}
                >
                  {t === 'B' ? 'B-ALL' : t === 'T' ? 'T-ALL' : 'Burkitt'}
                </button>
              ))}
            </div>
          </div>
          <div className="flex items-center justify-between border-b border-gray-50 pb-3">
            <span className="text-sm font-medium text-gray-700">巨块病变 (Bulky)</span>
            <button
              onClick={() => setIsBulky(!isBulky)}
              className={`w-12 h-6 rounded-full transition-colors relative ${isBulky ? 'bg-blue-500' : 'bg-gray-300'}`}
            >
              <div className={`absolute top-1 bg-white w-4 h-4 rounded-full transition-transform ${isBulky ? 'left-7' : 'left-1'}`} />
            </button>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-gray-700">初诊 WBC</span>
            <span className="text-sm font-bold text-blue-600">{wbc} ×10⁹/L</span>
          </div>
        </div>
      </IOSCard>

      {/* 风险等级展示 */}
      <div className={`mx-1 mb-6 p-4 rounded-2xl border ${risk.borderColor} ${risk.bgColor} flex items-center justify-between`}>
        <div>
          <div className="text-[10px] uppercase font-bold text-gray-400 mb-1">当前风险评定</div>
          <div className={`text-lg font-black ${risk.color}`}>{risk.level}</div>
        </div>
        <div className={`w-3 h-3 rounded-full animate-pulse ${risk.color.replace('text', 'bg')}`} />
      </div>

      {/* 处理流程 (表6/7) */}
      <IOSCard title="防治处理建议 (表6/7)">
        <div className="space-y-4">
          {/* 水化方案 */}
          <div className="bg-white border border-blue-100 rounded-xl p-3 shadow-sm">
            <div className="flex items-center mb-2">
              <div className="w-1.5 h-4 bg-blue-500 rounded-full mr-2" />
              <h4 className="text-xs font-bold text-blue-800">高强度水化方案</h4>
            </div>
            <div className="grid grid-cols-2 gap-2 mb-2">
              <div className="bg-blue-50/50 p-2 rounded-lg">
                <div className="text-[10px] text-blue-400">日总入量</div>
                <div className="text-sm font-bold text-blue-700">{hydrationVolume > 0 ? `${hydrationVolume.toFixed(0)} ml` : '--'}</div>
              </div>
              <div className="bg-blue-50/50 p-2 rounded-lg">
                <div className="text-[10px] text-blue-400">建议滴速</div>
                <div className="text-sm font-bold text-blue-700">{dripRate} ml/h</div>
              </div>
            </div>
            <p className="text-[10px] text-blue-600 leading-relaxed">
              * 维持尿量: 儿童 > 100ml/(m²·h)；<br/>
              * 碱化尿液: 仅在存在高尿酸血症时考虑，维持 pH 7.0-7.5。
            </p>
          </div>

          {/* 药物选择 */}
          <div className="bg-gray-50 rounded-xl p-3">
            <h4 className="text-xs font-bold text-gray-700 mb-2">药物干预建议</h4>
            <div className="space-y-2">
              <div className="flex items-start space-x-2">
                <span className="text-blue-500 mt-0.5">●</span>
                <span className="text-[11px] text-gray-600">
                  {risk.level.includes('High') 
                    ? '首选拉布立海 (0.2mg/kg.d)，若禁忌则用非布司他。' 
                    : '首选非布司他或别嘌醇 (300-450mg/m².d)。'}
                </span>
              </div>
              <div className="flex items-start space-x-2">
                <span className="text-blue-500 mt-0.5">●</span>
                <span className="text-[11px] text-gray-600">
                  电解质监测: {risk.level.includes('High') ? '每 4-6 小时' : '每 8-12 小时'}一次。
                </span>
              </div>
            </div>
          </div>
        </div>
      </IOSCard>

      {/* 诊断标准 (表3/5) */}
      <IOSCard title="TLS 诊断标准 (Cairo-Bishop)">
        <div className="space-y-4">
          <div className="p-3 bg-purple-50 rounded-xl border border-purple-100">
            <h4 className="text-[11px] font-bold text-purple-800 mb-2">实验室 TLS (LTLS) - 表3</h4>
            <div className="grid grid-cols-2 gap-x-4 gap-y-2 text-[10px] text-purple-700">
              <div className="flex justify-between border-b border-purple-100 pb-1">
                <span>尿酸 (UA)</span> <span>≥ 476 μmol/L</span>
              </div>
              <div className="flex justify-between border-b border-purple-100 pb-1">
                <span>血钾 (K)</span> <span>≥ 6.0 mmol/L</span>
              </div>
              <div className="flex justify-between border-b border-purple-100 pb-1">
                <span>血磷 (P)</span> <span>≥ 2.1 mmol/L</span>
              </div>
              <div className="flex justify-between border-b border-purple-100 pb-1">
                <span>血钙 (Ca)</span> <span>≤ 1.75 mmol/L</span>
              </div>
            </div>
            <div className="mt-2 text-[9px] text-purple-500 italic">注：或较基线变化 > 25%。符合 ≥ 2 项即可诊断。</div>
          </div>

          <div className="p-3 bg-red-50 rounded-xl border border-red-100">
            <h4 className="text-[11px] font-bold text-red-800 mb-2">临床 TLS (CTLS) - 表5</h4>
            <div className="text-[10px] text-red-700 space-y-1.5">
              <p className="flex justify-between"><span>● 肾脏损伤:</span> <span>肌酐 ≥ 1.5倍 ULN</span></p>
              <p className="flex justify-between"><span>● 心脏受累:</span> <span>心律失常 / 猝死</span></p>
              <p className="flex justify-between"><span>● 神经症状:</span> <span>惊厥 / 癫痫发作</span></p>
            </div>
            <div className="mt-2 text-[9px] text-red-500 italic">注：必须在符合 LTLS 的基础上出现上述症状。</div>
          </div>
        </div>
      </IOSCard>

      <div className="px-4 text-[10px] text-gray-400 text-center">
        依据《SCCCG-ALL-2025协议》与《血液病宝典》TLS防治章节整理
      </div>
    </div>
  );
};

export default TLSModule;

import React, { useState } from 'react';
import IOSCard from './IOSCard';
import { PatientInfo } from '../types';

interface Props {
  patient: PatientInfo;
  bsa: number;
}

const TLSModule: React.FC<Props> = ({ patient, bsa }) => {
  const [lineage, setLineage] = useState<'B' | 'T' | 'Burkitt'>('B');
  const [isBulky, setIsBulky] = useState(false);
  const [hasLTLS, setHasLTLS] = useState(false);

  const wbc = parseFloat(patient.initialWbc) || 0;

  // 1. 风险分层 (严格参照表4)
  const getRiskStratification = () => {
    // 高危: Burkitt/B-ALL, 或 WBC >= 100, 或已存在实验室TLS
    if (lineage === 'Burkitt' || wbc >= 100 || hasLTLS) {
      return { 
        level: '高危 (High Risk)', 
        color: 'text-red-600', 
        bgColor: 'bg-red-50', 
        borderColor: 'border-red-100',
        hydration: 3000,
        monitor: '每 4-6 小时',
        drug: '首选 拉布立海 (Rasburicase)'
      };
    }
    // 中危: WBC 25-100, 或 伴巨块病变
    if (wbc >= 25 || isBulky) {
      return { 
        level: '中危 (Intermediate Risk)', 
        color: 'text-orange-500', 
        bgColor: 'bg-orange-50', 
        borderColor: 'border-orange-100',
        hydration: 2500,
        monitor: '每 8-12 小时',
        drug: '别嘌醇 或 非布司他'
      };
    }
    // 低危: WBC < 25 且 无巨块
    return { 
      level: '低危 (Low Risk)', 
      color: 'text-green-600', 
      bgColor: 'bg-green-50', 
      borderColor: 'border-green-100',
      hydration: 2000,
      monitor: '每日一次',
      drug: '观察 或 别嘌醇'
    };
  };

  const risk = getRiskStratification();

  // 2. 水化量计算 (基于风险等级的 BSA 自动计算)
  const hydrationVolume = bsa > 0 ? bsa * risk.hydration : 0;
  const dripRate = hydrationVolume > 0 ? (hydrationVolume / 24).toFixed(1) : '0';

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300 pb-20">
      {/* 风险评估输入 */}
      <IOSCard title="风险因子评估 (表4)">
        <div className="space-y-4">
          <div className="flex items-center justify-between border-b border-gray-50 pb-3">
            <span className="text-sm font-medium text-gray-700">疾病类型</span>
            <div className="flex bg-gray-100 p-1 rounded-lg">
              {(['B', 'T', 'Burkitt'] as const).map((t) => (
                <button
                  key={t}
                  onClick={() => setLineage(t)}
                  className={`px-3 py-1 text-xs rounded-md transition-all ${
                    lineage === t ? 'bg-white shadow-sm text-blue-600 font-bold' : 'text-gray-500'
                  }`}
                >
                  {t === 'B' ? 'B-ALL' : t === 'T' ? 'T-ALL' : 'Burkitt'}
                </button>
              ))}
            </div>
          </div>
          <div className="flex items-center justify-between border-b border-gray-50 pb-3">
            <div className="flex flex-col">
              <span className="text-sm font-medium text-gray-700">巨块病变 (Bulky)</span>
              <span className="text-[10px] text-gray-400">纵隔肿块 > 1/3 胸径或淋巴结 > 10cm</span>
            </div>
            <button
              onClick={() => setIsBulky(!isBulky)}
              className={`w-12 h-6 rounded-full transition-colors relative ${isBulky ? 'bg-blue-500' : 'bg-gray-300'}`}
            >
              <div className={`absolute top-1 bg-white w-4 h-4 rounded-full transition-transform ${isBulky ? 'left-7' : 'left-1'}`} />
            </button>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-gray-700">初诊 WBC</span>
            <span className="text-sm font-bold text-blue-600">{wbc} ×10⁹/L</span>
          </div>
          <div className="flex items-center justify-between border-t border-gray-50 pt-3">
            <span className="text-sm font-medium text-gray-700">已存在实验室TLS?</span>
            <button
              onClick={() => setHasLTLS(!hasLTLS)}
              className={`w-12 h-6 rounded-full transition-colors relative ${hasLTLS ? 'bg-red-500' : 'bg-gray-300'}`}
            >
              <div className={`absolute top-1 bg-white w-4 h-4 rounded-full transition-transform ${hasLTLS ? 'left-7' : 'left-1'}`} />
            </button>
          </div>
        </div>
      </IOSCard>

      {/* 风险等级展示 */}
      <div className={`mx-1 mb-6 p-4 rounded-2xl border ${risk.borderColor} ${risk.bgColor} flex items-center justify-between transition-all duration-300`}>
        <div>
          <div className="text-[10px] uppercase font-bold text-gray-400 mb-1">风险分层结果</div>
          <div className={`text-lg font-black ${risk.color}`}>{risk.level}</div>
        </div>
        <div className={`w-3 h-3 rounded-full animate-pulse ${risk.color.replace('text', 'bg')}`} />
      </div>

      {/* 处理流程 (表6/7) */}
      <IOSCard title="防治处理建议 (表6/7)">
        <div className="space-y-4">
          <div className="bg-white border border-blue-100 rounded-xl p-3 shadow-sm">
            <div className="flex items-center mb-2">
              <div className="w-1.5 h-4 bg-blue-500 rounded-full mr-2" />
              <h4 className="text-xs font-bold text-blue-800">水化方案 (依据BSA自动计算)</h4>
            </div>
            <div className="grid grid-cols-2 gap-2 mb-2">
              <div className="bg-blue-50/50 p-2 rounded-lg text-center">
                <div className="text-[10px] text-blue-400">日总入量</div>
                <div className="text-sm font-bold text-blue-700">{hydrationVolume > 0 ? `${Math.round(hydrationVolume)} ml` : '--'}</div>
                <div className="text-[9px] text-blue-300">({risk.hydration}ml/m²)</div>
              </div>
              <div className="bg-blue-50/50 p-2 rounded-lg text-center">
                <div className="text-[10px] text-blue-400">建议滴速</div>
                <div className="text-sm font-bold text-blue-700">{dripRate} ml/h</div>
                <div className="text-[9px] text-blue-300">(24小时平均)</div>
              </div>
            </div>
            <p className="text-[10px] text-blue-600 leading-relaxed px-1 italic">
              * 目标尿量: 儿童 > 100ml/(m²·h)；成人 > 100ml/h。<br/>
              * 维持尿比重 &le; 1.010。
            </p>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="p-3 bg-gray-50 rounded-xl">
              <h5 className="text-[10px] font-bold text-gray-400 uppercase mb-1">降尿酸药物</h5>
              <p className="text-[11px] font-semibold text-gray-700 leading-tight">{risk.drug}</p>
            </div>
            <div className="p-3 bg-gray-50 rounded-xl">
              <h5 className="text-[10px] font-bold text-gray-400 uppercase mb-1">监测频率</h5>
              <p className="text-[11px] font-semibold text-gray-700 leading-tight">{risk.monitor}</p>
            </div>
          </div>
        </div>
      </IOSCard>

      {/* 诊断标准 (表3/5) */}
      <IOSCard title="实验室 TLS (LTLS) 诊断标准 - 表3">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px]">
            <thead>
              <tr className="text-gray-400 border-b border-gray-50">
                <th className="pb-2 font-medium">指标</th>
                <th className="pb-2 font-medium">阈值</th>
                <th className="pb-2 font-medium">基线变化</th>
              </tr>
            </thead>
            <tbody className="text-gray-600 divide-y divide-gray-50">
              <tr><td className="py-2">尿酸 (UA)</td><td className="py-2 font-medium">&ge; 476 &mu;mol/L</td><td className="py-2 text-red-400">&uarr; 25%</td></tr>
              <tr><td className="py-2">血钾 (K)</td><td className="py-2 font-medium">&ge; 6.0 mmol/L</td><td className="py-2 text-red-400">&uarr; 25%</td></tr>
              <tr><td className="py-2">血磷 (P)</td><td className="py-2 font-medium">&ge; 2.1 mmol/L*</td><td className="py-2 text-red-400">&uarr; 25%</td></tr>
              <tr><td className="py-2">血钙 (Ca)</td><td className="py-2 font-medium">&le; 1.75 mmol/L</td><td className="py-2 text-red-400">&darr; 25%</td></tr>
            </tbody>
          </table>
          <p className="mt-2 text-[9px] text-gray-400 italic">* 儿童血磷 > 1.45 mmol/L (成人 > 1.45 mmol/L)。LTLS需符合以上2项或更多。</p>
        </div>
      </IOSCard>

      <IOSCard title="临床 TLS (CTLS) 分级标准 - 表5">
        <div className="space-y-3">
          <div className="grid grid-cols-4 gap-1 text-center mb-1">
            {['指标', '1级', '2级', '3级+'].map(h => <div key={h} className="text-[9px] font-bold text-gray-400">{h}</div>)}
          </div>
          {[
            { name: '肌酐', g1: '1.5x', g2: '1.5-3x', g3: '>3x ULN' },
            { name: '心律失常', g1: '无需干预', g2: '非药物干预', g3: '需药物干预' },
            { name: '惊厥', g1: '-', g2: '1次/局限', g3: '泛发/持续' },
          ].map(row => (
            <div key={row.name} className="grid grid-cols-4 gap-1 items-center border-b border-gray-50 pb-2">
              <div className="text-[10px] font-bold text-gray-700">{row.name}</div>
              <div className="text-[9px] text-gray-500">{row.g1}</div>
              <div className="text-[9px] text-gray-500">{row.g2}</div>
              <div className="text-[9px] text-red-500 font-medium">{row.g3}</div>
            </div>
          ))}
          <p className="text-[9px] text-gray-400 leading-tight">CTLS 定义：LTLS + 至少一个器官功能受损。等级越高，临床风险越大。</p>
        </div>
      </IOSCard>

      <div className="px-4 text-[10px] text-gray-400 text-center mb-4">
        * 依据《SCCCG-ALL-2025》及《血液病宝典》TLS 防治指南整理
      </div>
    </div>
  );
};

export default TLSModule;

