import React, { useState, useMemo } from 'react';
import { 
  User, 
  ShieldAlert, 
  Dna, 
  Brain, 
  Activity, 
  ThermometerSnowflake 
} from 'lucide-react';
import PatientInfoForm from './components/PatientInfoForm';
import RiskStratification from './components/RiskStratification';
import MPALModule from './components/MPALModule';
import CNSLModule from './components/CNSLModule';
import LASPModule from './components/LASPModule';
import TLSModule from './components/TLSModule';
import { PatientInfo } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('patient');
  const [patient, setPatient] = useState<PatientInfo>({
    name: '',
    gender: '',
    age: '',
    height: '',
    weight: '',
    initialWbc: ''
  });

  const bsa = useMemo(() => {
    const h = parseFloat(patient.height);
    const w = parseFloat(patient.weight);
    if (isNaN(h) || isNaN(w)) return 0;
    return Math.sqrt((h * w) / 3600);
  }, [patient.height, patient.weight]);

  const renderContent = () => {
    const components: Record<string, React.ReactNode> = {
      patient: <PatientInfoForm patient={patient} setPatient={setPatient} bsa={bsa} />,
      risk: <RiskStratification patient={patient} />,
      mpal: <MPALModule />,
      cnsl: <CNSLModule />,
      lasp: <LASPModule bsa={bsa} patient={patient} />,
      tls: <TLSModule patient={patient} bsa={bsa} />,
    };
    return components[activeTab] || null;
  };

  const tabs = [
    { id: 'patient', icon: User, label: '患者' },
    { id: 'risk', icon: ShieldAlert, label: '危险度' },
    { id: 'mpal', icon: Dna, label: 'MPAL' },
    { id: 'cnsl', icon: Brain, label: 'CNSL' },
    { id: 'lasp', icon: Activity, label: '凝血' },
    { id: 'tls', icon: ThermometerSnowflake, label: 'TLS' },
  ];

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-[#F2F2F7] selection:bg-blue-100">
      {/* Dynamic Background Element */}
      <div className="fixed top-[-10%] left-[-10%] w-[40%] h-[30%] bg-blue-400/10 blur-[100px] pointer-events-none" />
      <div className="fixed bottom-[-5%] right-[-5%] w-[40%] h-[30%] bg-purple-400/10 blur-[100px] pointer-events-none" />

      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/60 ios-blur border-b border-gray-200/50 px-4 py-5">
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold text-blue-500 uppercase tracking-tighter mb-0.5">Clinical Tool</span>
          <h1 className="text-xl font-black text-gray-900 tracking-tight">SCCCG-ALL-2025</h1>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-28 px-4 pt-6">
        {renderContent()}
      </main>

      {/* Tab Bar */}
      <nav className="fixed bottom-4 left-4 right-4 max-w-[calc(448px-2rem)] mx-auto bg-white/80 ios-blur border border-white/50 shadow-[0_8px_32px_rgba(0,0,0,0.1)] rounded-[32px] px-2 py-2 z-50">
        <div className="flex justify-around items-center">
          {tabs.map((tab) => {
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`relative flex flex-col items-center justify-center flex-1 py-2 transition-all duration-300 ${
                  isActive ? 'text-blue-600 scale-110' : 'text-gray-400 hover:text-gray-600'
                }`}
              >
                <tab.icon size={20} strokeWidth={isActive ? 2.5 : 2} />
                <span className={`text-[9px] mt-1 font-bold ${isActive ? 'opacity-100' : 'opacity-70'}`}>
                  {tab.label}
                </span>
                {isActive && (
                  <div className="absolute -bottom-1 w-1 h-1 bg-blue-600 rounded-full" />
                )}
              </button>
            );
          })}
        </div>
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import IOSCard from './IOSCard';
import { PatientInfo } from '../types';

interface Props {
  patient: PatientInfo;
}

const RiskStratification: React.FC<Props> = ({ patient }) => {
  const [mrd, setMrd] = useState({ d15: '', d33: '', w12: '' });
  const [selectedGenes, setSelectedGenes] = useState<string[]>([]);
  const [extra, setExtra] = useState<string[]>([]);

  const toggleGene = (gene: string) => {
    setSelectedGenes(prev => prev.includes(gene) ? prev.filter(g => g !== gene) : [...prev, gene]);
  };

  const toggleExtra = (item: string) => {
    setExtra(prev => prev.includes(item) ? prev.filter(i => i !== item) : [...prev, item]);
  };

  const getRiskLevel = () => {
    const age = parseFloat(patient.age);
    const wbc = parseFloat(patient.initialWbc);
    const mrd15 = parseFloat(mrd.d15);
    const mrd33 = parseFloat(mrd.d33);
    const mrdW12 = parseFloat(mrd.w12);

    const isHR = 
      mrd15 >= 10 || 
      mrd33 >= 1 || 
      mrdW12 >= 0.01 ||
      selectedGenes.some(g => ['MLL', 'LowHypo', 'iAMP21', 'IKZF1+', 'TCF3-HLF'].includes(g)) ||
      extra.includes('Failure');

    if (isHR) return { 
      level: '高危 (High Risk)', 
      color: 'text-white', 
      bg: 'bg-gradient-to-br from-red-500 to-red-700',
      shadow: 'shadow-red-200',
      desc: '需强化化疗及密切监测'
    };

    const isIR = 
      age >= 10 || 
      wbc >= 50 || 
      extra.includes('T-ALL') || 
      extra.includes('CNSL/TL') ||
      selectedGenes.includes('Ph+') || 
      selectedGenes.includes('Ph-like') || 
      selectedGenes.includes('t(1;19)') ||
      (mrd15 >= 0.1 && mrd15 < 10) ||
      (mrd33 >= 0.01 && mrd33 < 1);

    if (isIR) return { 
      level: '中危 (Intermediate Risk)', 
      color: 'text-white', 
      bg: 'bg-gradient-to-br from-orange-400 to-orange-600',
      shadow: 'shadow-orange-200',
      desc: '标准方案治疗，评估后续反应'
    };

    if (age >= 1 && age < 10 && wbc < 50 && mrd15 < 0.1 && mrd33 < 0.01) {
      return { 
        level: '低危 (Low Risk)', 
        color: 'text-white', 
        bg: 'bg-gradient-to-br from-emerald-400 to-emerald-600',
        shadow: 'shadow-emerald-200',
        desc: '预后良好，按常规方案执行'
      };
    }

    return { 
      level: '评估中...', 
      color: 'text-gray-400', 
      bg: 'bg-gray-100', 
      shadow: 'shadow-none',
      desc: '请完善上方所有关键数据'
    };
  };

  const risk = getRiskLevel();

  return (
    <div className="animate-in fade-in slide-in-from-bottom-6 duration-500">
      <div className={`p-6 rounded-[32px] mb-6 text-center ${risk.bg} ${risk.shadow} shadow-2xl transition-all duration-500 transform hover:scale-[1.02]`}>
        <div className="text-[10px] font-bold text-white/60 uppercase tracking-widest mb-1">Assessment Result</div>
        <div className={`text-2xl font-black ${risk.color} mb-1`}>{risk.level}</div>
        <div className="text-white/80 text-[11px] font-medium">{risk.desc}</div>
      </div>

      <IOSCard title="疗效评估 (MRD %)">
        <div className="grid grid-cols-3 gap-3">
          {['d15', 'd33', 'w12'].map((day) => (
            <div key={day} className="flex flex-col items-center bg-gray-50 p-3 rounded-2xl">
              <span className="text-[10px] font-bold text-gray-400 uppercase mb-2">{day}</span>
              <input 
                type="number" 
                placeholder="0.00" 
                value={(mrd as any)[day]}
                onChange={(e) => setMrd(prev => ({ ...prev, [day]: e.target.value }))}
                className="w-full text-center text-sm font-bold text-gray-900 bg-transparent outline-none border-b border-gray-200 focus:border-blue-500"
              />
            </div>
          ))}
        </div>
      </IOSCard>

      <IOSCard title="遗传学异常">
        <div className="grid grid-cols-3 gap-2">
          {['Ph+', 'Ph-like', 'MLL', 't(1;19)', 'LowHypo', 'iAMP21', 'IKZF1+', 'TCF3-HLF'].map(gene => (
            <button 
              key={gene}
              onClick={() => toggleGene(gene)}
              className={`text-[10px] font-bold py-3 px-1 rounded-xl border-2 transition-all duration-300 ${
                selectedGenes.includes(gene) 
                  ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-100 scale-95' 
                  : 'bg-white border-gray-50 text-gray-500 hover:border-blue-200'
              }`}
            >
              {gene}
            </button>
          ))}
        </div>
      </IOSCard>

      <IOSCard title="临床合并因素">
        <div className="space-y-3">
          {[
            { id: 'T-ALL', label: 'T-ALL 亚型', icon: '🧬' },
            { id: 'CNSL/TL', label: '伴 CNSL 或睾丸受累 (TL)', icon: '🧠' },
            { id: 'Failure', label: 'd33 未达 CR / 瘤灶缩小不足', icon: '⚠️' }
          ].map(item => (
            <button 
              key={item.id}
              onClick={() => toggleExtra(item.id)}
              className={`w-full text-left p-4 rounded-2xl border-2 flex justify-between items-center transition-all ${
                extra.includes(item.id) 
                  ? 'bg-blue-50/50 border-blue-500 text-blue-700' 
                  : 'bg-gray-50 border-transparent text-gray-500'
              }`}
            >
              <div className="flex items-center">
                <span className="mr-3 text-lg">{item.icon}</span>
                <span className="text-xs font-bold">{item.label}</span>
              </div>
              <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                extra.includes(item.id) ? 'border-blue-500 bg-blue-500' : 'border-gray-200'
              }`}>
                {extra.includes(item.id) && <div className="w-1.5 h-1.5 bg-white rounded-full" />}
              </div>
            </button>
          ))}
        </div>
      </IOSCard>
    </div>
  );
};

export default RiskStratification;

import React, { useState } from 'react';
import IOSCard from './IOSCard';
import { PatientInfo } from '../types';

interface Props {
  patient: PatientInfo;
  bsa: number;
}

const TLSModule: React.FC<Props> = ({ patient, bsa }) => {
  const [lineage, setLineage] = useState<'B' | 'T' | 'Burkitt'>('B');
  const [isBulky, setIsBulky] = useState(false);
  const [hasLTLS, setHasLTLS] = useState(false);

  const wbc = parseFloat(patient.initialWbc) || 0;

  const getRiskStratification = () => {
    if (lineage === 'Burkitt' || wbc >= 100 || hasLTLS) {
      return { 
        level: '高危 (High Risk)', 
        color: 'text-red-600', 
        bgColor: 'bg-red-50', 
        borderColor: 'border-red-100',
        hydration: 3000,
        monitor: '每 4-6 小时',
        drug: '拉布立海'
      };
    }
    if (wbc >= 25 || isBulky) {
      return { 
        level: '中危 (Intermediate Risk)', 
        color: 'text-orange-500', 
        bgColor: 'bg-orange-50', 
        borderColor: 'border-orange-100',
        hydration: 2500,
        monitor: '每 8-12 小时',
        drug: '非布司他'
      };
    }
    return { 
      level: '低危 (Low Risk)', 
      color: 'text-emerald-600', 
      bgColor: 'bg-emerald-50', 
      borderColor: 'border-emerald-100',
      hydration: 2000,
      monitor: '每日一次',
      drug: '别嘌醇'
    };
  };

  const risk = getRiskStratification();
  const hydrationVolume = bsa > 0 ? bsa * risk.hydration : 0;
  const dripRate = hydrationVolume > 0 ? (hydrationVolume / 24).toFixed(1) : '0';

  return (
    <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 pb-20">
      <IOSCard title="风险因子">
        <div className="space-y-4">
          <div className="flex bg-gray-100/50 p-1.5 rounded-2xl">
            {(['B', 'T', 'Burkitt'] as const).map((t) => (
              <button
                key={t}
                onClick={() => setLineage(t)}
                className={`flex-1 py-2 text-xs font-black rounded-xl transition-all ${
                  lineage === t ? 'bg-white shadow-md text-blue-600' : 'text-gray-400'
                }`}
              >
                {t === 'B' ? 'B-ALL' : t === 'T' ? 'T-ALL' : 'Burkitt'}
              </button>
            ))}
          </div>

          <div className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl">
            <div className="flex flex-col">
              <span className="text-xs font-bold text-gray-700">巨块病变 (Bulky)</span>
              <span className="text-[9px] text-gray-400 mt-0.5">纵隔块>1/3或淋巴结>10cm</span>
            </div>
            <button
              onClick={() => setIsBulky(!isBulky)}
              className={`w-14 h-8 rounded-full transition-all relative p-1 ${isBulky ? 'bg-blue-600' : 'bg-gray-300'}`}
            >
              <div className={`bg-white w-6 h-6 rounded-full shadow-sm transition-transform duration-300 ${isBulky ? 'translate-x-6' : 'translate-x-0'}`} />
            </button>
          </div>

          <div className="flex items-center justify-between px-2">
            <span className="text-xs font-bold text-gray-500">已符合实验室诊断?</span>
            <button
              onClick={() => setHasLTLS(!hasLTLS)}
              className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${
                hasLTLS ? 'bg-red-500 border-red-500 text-white' : 'border-gray-100 text-gray-400'
              }`}
            >
              {hasLTLS ? 'YES' : 'NO'}
            </button>
          </div>
        </div>
      </IOSCard>

      <div className={`p-5 rounded-[28px] border-2 ${risk.borderColor} ${risk.bgColor} mb-6 transition-all duration-300`}>
        <div className="flex items-center justify-between">
          <div>
            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Risk Stratification</div>
            <div className={`text-xl font-black ${risk.color}`}>{risk.level}</div>
          </div>
          <div className={`p-3 rounded-full ${risk.color.replace('text', 'bg').replace('600', '100')} ${risk.color}`}>
            <ShieldAlert size={24} />
          </div>
        </div>
      </div>

      <IOSCard title="水化方案建议">
        <div className="bg-blue-600 rounded-3xl p-6 text-white shadow-xl shadow-blue-100">
          <div className="flex justify-between items-end mb-6">
            <div>
              <div className="text-blue-100 text-[10px] font-bold uppercase tracking-wider mb-1">Daily Intake</div>
              <div className="text-3xl font-black">{Math.round(hydrationVolume)} <span className="text-sm font-normal opacity-60">ml</span></div>
            </div>
